import SwiftailBase

/// The state machine for one TCP connection (RFC 9293 §§3.3.2 and 3.10).
///
/// A value type without sockets, clocks, or random numbers. Inputs are received segments (`receive(_:at:)`),
/// application calls (`write`, `read`, `finishWriting`, `close`, and `abort`), and time (`advance(to:)`). Outputs are
/// segments to send and events (`Output`). Takes ISN as an argument, generated by the stack per RFC 6528. The caller
/// invokes `advance(to:)` at `nextDeadline`, and time must never decrease between calls.
///
/// Creates an active open with `connect(from:to:initialSequenceNumber:at:)` and a passive open with
/// `accept(_:initialSequenceNumber:at:)` using the SYN received by the stack. LISTEN is outside this type (contract
/// behavior S3).
///
/// Schedules ACKs by deadline. In-order data is due in 40ms or immediately when 2×MSS accumulates. Out-of-order data,
/// data filling a gap, FIN, and out-of-window segments are due immediately. An immediate ACK goes out in the `receive`
/// output for that segment (one per segment, RFC 5681 §4.2). Only ACKs with a 40ms deadline go out in `advance(to:)`.
/// Thus only ACKs for in-order data are coalesced within a group (one per 2×MSS, MUST-58 and 59, contract behaviors F5
/// and N4). An outgoing data segment carries the ACK and clears its deadline.
///
/// This file contains the type declaration and state. Opening, segment reception, sending, application calls, and
/// timers are in the corresponding `TCPConnection+…` files. Contract `docs/contracts/SwiftailNetstack.md` behaviors T,
/// R, F, and X. Notes `docs/protocol-notes/tcp-netstack.md` §4.
package struct TCPConnection: Sendable {
    /// The connection state (RFC 9293 §3.3.2). The stack handles LISTEN.
    package enum State: Sendable, Equatable {
        /// SYN-SENT. Sent SYN and waiting for SYN-ACK.
        case synSent
        /// SYN-RECEIVED. Answered SYN with SYN-ACK and waiting for ACK.
        case synReceived
        /// ESTABLISHED. Both sides exchange data.
        case established
        /// FIN-WAIT-1. Sent the local FIN and waiting for its acknowledgment.
        case finWait1
        /// FIN-WAIT-2. The local FIN was acknowledged and the peer's FIN is pending.
        case finWait2
        /// CLOSE-WAIT. Received the peer's FIN and waiting for the application to close.
        case closeWait
        /// CLOSING. The FINs crossed, so wait for acknowledgment of the local FIN.
        case closing
        /// LAST-ACK. Waiting for acknowledgment of the local FIN sent after the peer's FIN.
        case lastAck
        /// TIME-WAIT. The side that closed first stays to acknowledge retransmissions of the peer's FIN (contract behavior T6).
        case timeWait
        /// CLOSED. The connection has ended and emits nothing further.
        case closed
    }

    /// State machine output. Process in emission order (contract behavior S10).
    package enum Output: Sendable, Equatable {
        /// A segment to send to the peer. Emitted in sequence order.
        case segment(TCPSegment)
        /// An event to report to the application or stack.
        case event(Event)
    }

    /// An event to report to the application or stack (contract “Structure,” item 1).
    package enum Event: Sendable, Equatable {
        /// The three-way handshake completed. For a passive open, the stack puts the connection in the accept queue.
        case established
        /// Bytes became readable after there were none. Wakes a waiting `read`.
        case readable
        /// A full send buffer prevented `write` from accepting all bytes, and acknowledgment freed space. Wakes a waiting `write`.
        case writable
        /// The peer closed its write side (FIN). All data received before it can be read (RFC 9293 §3.10.7.4 step eight, MUST-12).
        case endOfStream
        /// The connection ended. No output follows.
        case closed(CloseReason)
    }

    /// The reason the connection ended.
    package enum CloseReason: Sendable, Equatable {
        /// Both FINs were exchanged and the connection ended (FIN acknowledged in LAST-ACK or TIME-WAIT completed). Unread data remains.
        case finished
        /// The peer aborted with RST (RFC 9293 §3.10.7.4 step two). SYN-RECEIVED on a passive open means “return to
        /// LISTEN.” Since it has not emitted `.established`, the stack removes it silently without notifying the
        /// application. Clears the buffers.
        case reset
        /// The active open was refused (RST in response to SYN), or the peer advertised an MSS below 64 (contract behaviors T3 and X9).
        case refused
        /// The peer did not respond. The limits are 7 retransmissions for SYN or SYN-ACK, 15 for data, 15 zero-window
        /// probes, 9 keep-alives, and 60 seconds in FIN-WAIT-2 after `close` (contract behaviors R4, F8, T8, and T6).
        /// This also applies when a connection released by the application with `close` reaches the limit with a zero
        /// window and no progress. Sends RST if the peer replied (contract behavior F8). Clears the buffers.
        case timedOut
        /// This side aborted because of `abort`, `close` with unread data, or data arriving after `close` (SHLD-3). Clears the buffers.
        case aborted
    }

    /// The reason a passive open was rejected.
    package enum AcceptError: Error, Sendable, Equatable {
        /// The supplied segment is not a SYN without ACK or RST. The stack's LISTEN rules (TCP notes §4.2) should have
        /// filtered it first. Sends nothing.
        case notInitialSYN
        /// The peer's advertised MSS is below 64 (contract behavior X9). Includes the RST replying to the SYN in the
        /// format for a segment without ACK (RFC 9293 §3.10.7.1).
        case unacceptableMaximumSegmentSize(reset: TCPSegment)
    }

    // MARK: Constants

    /// The tailnet MTU (contract decision D9).
    static let maximumTransmissionUnit = 1280
    /// The local Window Scale shift (contract behavior F2, the smallest value that satisfies `65535 << 3 >= 262144`).
    static let ownWindowShift = 3
    /// The cap on the peer's shift (RFC 7323 §2.3).
    static let maximumWindowShift = 14
    /// The window carried in SYN and SYN-ACK. The SYN window is unscaled (RFC 7323 §2.2), so uses the 16-bit maximum.
    /// Uses the receive window cap if it is smaller (`receiveWindowLimit`).
    static let synchronizeWindow = min(Int(UInt16.max), ReceiveBuffer.defaultCapacity)
    /// The receive window for a connection in the listener's queue that the application has yet to accept. The receive
    /// buffer grows to cover what was written, so a fully open window would let a peer allocate 256KiB per connection
    /// before acceptance. 16KiB is the smallest power of 2 that accommodates the peer's first window (10×MSS per RFC
    /// 6928, 12,400 bytes at MSS 1240), fits directly in the unscaled SYN-ACK window field, and is a multiple of the
    /// local shift (3) (contract behavior M).
    static let unacceptedReceiveWindow = 16 * 1024
    /// Rejects establishment if the peer advertised an MSS below this value (contract behavior X9).
    static let minimumPeerSegmentSize = 64
    /// The SYN and SYN-ACK retransmission limit. Discards the connection at 247 seconds, when the timer for the seventh
    /// retransmission expires (contract behavior R4).
    static let synchronizeRetransmissionLimit = 7
    /// The data and FIN retransmission limit (contract behavior R4).
    static let dataRetransmissionLimit = 15
    /// The limit on zero-window probes with no ACK. For application-released connections, it limits probes without
    /// progress (contract behavior F8).
    static let zeroWindowProbeLimit = 15
    /// The maximum interval between zero-window probes (contract behavior F8).
    static let maximumZeroWindowProbeInterval = Duration.seconds(60)
    /// The delayed ACK deadline (contract behavior F5, less than 0.5 seconds per RFC 9293 §3.8.6.3 MUST-40).
    static let delayedAcknowledgmentTimeout = Duration.milliseconds(40)
    /// The sender SWS avoidance override interval (contract behavior F7, 0.1~1 seconds in RFC 9293 §3.8.6.2.1).
    static let sillyWindowOverrideTimeout = Duration.milliseconds(200)
    /// Keep-alive uses 2 hours idle, 75-second intervals, and 9 attempts (contract behavior T8, gVisor defaults). RFC
    /// 9293 §3.8.4 says off by default (MUST-25), but contract lead session decision N5 keeps it always on.
    static let keepaliveIdle = Duration.seconds(2 * 60 * 60)
    static let keepaliveInterval = Duration.seconds(75)
    static let keepaliveProbeLimit = 9
    /// TIME-WAIT (contract behavior T6, gVisor's value. 2MSL in RFC 9293 is 4 minutes).
    static let timeWaitDuration = Duration.seconds(60)
    /// The latest end after FIN retransmissions restart TIME-WAIT, 2MSL = 4 minutes from entry (RFC 9293 §3.6.1
    /// MUST-13. MSL is 2 minutes in the same RFC's glossary). The stack's TIME-WAIT record inherits this limit.
    static let maximumTimeWaitLifetime = Duration.seconds(240)
    /// The limit on time in FIN-WAIT-2 after `close` (contract behavior T6, gVisor linger default).
    static let finWait2Linger = Duration.seconds(60)

    // MARK: Connection

    /// The current state.
    package internal(set) var state: State
    /// The local address and port.
    package let localEndpoint: IPEndpoint
    /// The peer address and port.
    package let remoteEndpoint: IPEndpoint

    // MARK: Sender (RFC 9293 §3.3.1)

    /// ISS. Used only to construct SYN or SYN-ACK. It can be more than 2³¹ away after establishment, so it is not used in comparisons then.
    let initialSendSequence: SequenceNumber
    /// SND.UNA.
    package internal(set) var sendUnacknowledged: SequenceNumber
    /// SND.NXT. One past the highest number sent so far. Go-back-N after RTO leaves it in place and rewinds `transmitNext`.
    package internal(set) var sendNext: SequenceNumber
    /// The first sequence number of the next segment to send. Usually equals `sendNext`. On RTO expiration, rewinds to
    /// `sendUnacknowledged` and retransmits from there as slow start allows (contract behavior R7). Sending a range
    /// before `sendNext` is retransmission.
    var transmitNext: SequenceNumber
    /// SND.WND after applying window scaling.
    package internal(set) var sendWindow: Int
    /// The largest SND.WND received so far. This is MAX.SND.WND in RFC 5961 §5.2 and Max(SND.WND) for sender SWS avoidance.
    var maximumSendWindow: Int
    /// SND.WL1 and SND.WL2, the SEQ and ACK of the segment that last updated the window.
    var sendWindowUpdateSequence: SequenceNumber
    var sendWindowUpdateAcknowledgment: SequenceNumber
    /// The window on the previous ACK. Used for the duplicate ACK condition that the advertised window equals the previous one (RFC 5681 §2).
    var lastPeerWindow: Int
    /// Snd.Wind.Shift, the shift used to scale the received window (RFC 7323 §2.3). 0 when scaling is off.
    var sendWindowShift = 0
    /// Eff.snd.MSS, the data limit per outgoing segment (contract behavior T5).
    package internal(set) var sendMaximumSegmentSize: Int
    /// The send buffer. SYN and FIN use sequence numbers outside it.
    var sendBuffer: SendBuffer
    /// The application finished writing (`finishWriting` or `close`). Fixes the FIN number at `sendBuffer.endSequence`.
    var finRequested = false
    /// `write` could not accept all the bytes. Emits `.writable` when space becomes available.
    var isWriteBlocked = false

    // MARK: Receiver

    /// The MSS this side advertises. 1280 − IP header − 20 (contract behavior T5). Also used in the 2×RMSS delayed ACK
    /// threshold (RFC 9293 §3.8.6.3).
    let receiveMaximumSegmentSize: Int
    /// Rcv.Wind.Shift, the shift used to divide the advertised window (RFC 7323 §2.3). 0 when scaling is off.
    var receiveWindowShift = 0
    /// Whether the local SYN included Window Scale. Always true for an active open. For a passive open, true only when
    /// the peer's SYN had it (contract behavior F2).
    let offersWindowScale: Bool
    /// The peer's SYN (SYN-ACK) included SACK-Permitted. ACKs carry SACK blocks only in this case (RFC 2018 §4 MUST
    /// NOT, under contract behavior F5). The local SYN always includes SACK-Permitted for an active open and includes
    /// it for a passive open only when this value is true (contract behaviors T3 and T4).
    var peerPermitsSACK = false
    /// The receive buffer. Holds only the peer's data. FIN is tracked in `finReceived`.
    var receiveBuffer: ReceiveBuffer
    /// The receive window cap, which limits the sum of unread bytes and the advertised window. Normally the receive
    /// buffer's capacity. Only a connection queued by the stack on a listener starts with `unacceptedReceiveWindow` and
    /// opens when the application takes it (`openReceiveWindow(at:)`).
    var receiveWindowLimit: Int
    /// The farthest right edge advertised so far. It never moves left (SHLD-14), and bytes past it are not accepted
    /// (RFC 7323 §2.4 item 1 accepts anything inside the window of any transmitted ACK).
    var advertisedWindowEnd: SequenceNumber
    /// The peer's FIN was consumed.
    var finReceived = false
    /// The sequence number of the peer's FIN that arrived ahead of a gap. Consumes it once all preceding data arrives
    /// (RFC 9293 §3.10.7.4 SHLD-31).
    var pendingFinSequence: SequenceNumber?
    /// The application finished reading with `close`. Replies to later data with RST (SHLD-3). Zero-window probes and
    /// retransmissions into a reduced window end at the limit even if the peer replies (contract behavior F8).
    var readClosed = false
    /// The number of bytes received in order since the last ACK. Sends an immediate ACK at 2×RMSS (SHLD-19).
    var unacknowledgedByteCount = 0

    // MARK: Retransmission and Congestion Control

    var retransmissionEstimator = RTOEstimator()
    var congestionControl: NewRenoCongestionControl
    /// The number of retransmissions of the same segment (or SYN). Resets to 0 when `SND.UNA` advances.
    var retransmissionCount = 0
    /// The ACK on the current segment triggered fast retransmit (three duplicate ACKs or a partial ACK). Retransmit
    /// after placing even this segment's data in the receive buffer, because the retransmitted segment's first SACK
    /// block must represent the just-received data range
    /// (RFC 2018 4).
    var isFastRetransmitPending = false
    /// Received an acceptable ACK after the latest retransmission timer expiration. Determines whether to count that
    /// expiration toward the limit when the window shrinks to 0 (under contract behavior F8).
    var acknowledgedSinceRetransmissionTimeout = false
    /// The segment being timed for its round-trip time (one at a time, contract behavior R2). Discarded on
    /// retransmission (Karn, RFC 6298 §3).
    var roundTripSample: RoundTripSample?
    /// When SYN or SYN-ACK was first sent. If never retransmitted, provides the first round-trip sample at establishment.
    let synchronizeSentAt: ContinuousClock.Instant
    /// When data was last sent, used to determine idleness under RFC 5681 §4.1.
    var lastDataSentAt: ContinuousClock.Instant?
    /// Transmission statistics. The stack includes them in `.closed` when the connection ends.
    package internal(set) var statistics: Statistics

    // MARK: Timers

    var timers = ConnectionTimers()
    /// When the connection entered TIME-WAIT. The latest deadline to which FIN retransmissions may extend it
    /// (`maximumTimeWaitLifetime`) is measured from this time.
    var timeWaitEnteredAt: ContinuousClock.Instant?
    /// The number of zero-window probes sent without an ACK. On an application-released connection (`readClosed`),
    /// replies without progress (an ACK of new data or an open window) do not reduce it (contract behavior F8).
    var zeroWindowProbeCount = 0
    /// The interval until the next zero-window probe. Doubles per probe, up to 60 seconds.
    var zeroWindowProbeInterval = Duration.zero
    /// The number of keep-alive probes sent without a reply.
    var keepaliveProbeCount = 0
    var challengeLimiter = ChallengeACKLimiter()

    /// A segment being timed for round-trip time. `[start, end)` was first sent at `sentAt`.
    struct RoundTripSample: Sendable {
        var start: SequenceNumber
        var end: SequenceNumber
        var sentAt: ContinuousClock.Instant
    }

    /// Initialization shared by both opens. The open fills in peer values (IRS, window, MSS, shift).
    init(
        state: State,
        local: IPEndpoint,
        remote: IPEndpoint,
        initialSendSequence: SequenceNumber,
        initialReceiveSequence: SequenceNumber,
        offersWindowScale: Bool,
        receiveWindowLimit: Int = ReceiveBuffer.defaultCapacity,
        at now: ContinuousClock.Instant
    ) {
        self.state = state
        localEndpoint = local
        remoteEndpoint = remote
        self.initialSendSequence = initialSendSequence
        sendUnacknowledged = initialSendSequence
        sendNext = initialSendSequence.advanced(by: 1)
        transmitNext = sendNext
        sendWindow = 0
        maximumSendWindow = 0
        sendWindowUpdateSequence = initialReceiveSequence
        sendWindowUpdateAcknowledgment = initialSendSequence
        lastPeerWindow = 0
        let ownSize = Self.ownMaximumSegmentSize(for: local.address)
        receiveMaximumSegmentSize = ownSize
        sendMaximumSegmentSize = ownSize
        sendBuffer = SendBuffer(firstSequence: sendNext)
        self.offersWindowScale = offersWindowScale
        let receiveNext = initialReceiveSequence.advanced(by: 1)
        receiveBuffer = ReceiveBuffer(initialSequence: receiveNext)
        self.receiveWindowLimit = receiveWindowLimit
        advertisedWindowEnd = receiveNext.advanced(by: UInt32(min(Self.synchronizeWindow, receiveWindowLimit)))
        congestionControl = NewRenoCongestionControl(
            maximumSegmentSize: ownSize, initialSequenceNumber: initialSendSequence)
        synchronizeSentAt = now
        statistics = Statistics(openedAt: now)
    }

    // MARK: Readable Values

    /// RCV.NXT. If the peer's FIN was consumed, this is the number after it.
    package var receiveNext: SequenceNumber {
        receiveBuffer.nextSequence.advanced(by: finReceived ? 1 : 0)
    }

    /// The number of bytes the application can read now.
    package var readableByteCount: Int { receiveBuffer.readableCount }

    /// The remaining space in the send buffer, the maximum `write` can accept now.
    package var writableByteCount: Int { sendBuffer.freeSpace }

    /// The number of bytes left in the send buffer (unacknowledged + unsent).
    package var unacknowledgedSendByteCount: Int { sendBuffer.count }

    /// The peer closed its write side (FIN was consumed).
    package var hasReceivedEndOfStream: Bool { finReceived }

    /// The current RTO.
    package var retransmissionTimeout: Duration { retransmissionEstimator.retransmissionTimeout }

    /// The current cwnd.
    package var congestionWindow: Int { congestionControl.congestionWindow }

    // MARK: Helpers

    /// The MSS derived from the local MTU, 1280 − IP header (20 for IPv4, 40 for IPv6) − TCP header 20 (contract behavior T5, TCP notes §7).
    static func ownMaximumSegmentSize(for address: IPAddress) -> Int {
        maximumTransmissionUnit - (address.isIPv4 ? 20 : 40) - 20
    }

    /// The MSS when the peer's SYN omits the option, 536 for IPv4 and 1220 for IPv6 (RFC 9293 §3.7.1 MUST-15).
    static func defaultPeerMaximumSegmentSize(for address: IPAddress) -> Int {
        address.isIPv4 ? 536 : 1220
    }

    /// The data-side FIN number. Meaningful only when `finRequested` is true, after which no bytes are appended to the buffer.
    var finSequence: SequenceNumber { sendBuffer.endSequence }

    /// The local FIN was sent.
    var finSent: Bool { finRequested && sendNext == finSequence.advanced(by: 1) }

    /// The local FIN was acknowledged.
    var finAcknowledged: Bool { finRequested && sendUnacknowledged == finSequence.advanced(by: 1) }

    /// There is an unacknowledged sequence number (SYN, data, or FIN).
    var hasOutstandingData: Bool { sendUnacknowledged != sendNext }

    /// `SND.UNA + SND.WND`, the right edge the peer said it would accept.
    var sendWindowEnd: SequenceNumber { sendUnacknowledged.advanced(by: UInt32(clamping: sendWindow)) }

    /// Ends the connection. Clears the buffers unless `.finished`, because data after RST, timeout, or abort cannot be used.
    mutating func terminate(_ reason: CloseReason, into outputs: inout [Output]) {
        state = .closed
        timers.removeAll()
        roundTripSample = nil
        if reason != .finished {
            receiveBuffer = ReceiveBuffer(initialSequence: receiveBuffer.nextSequence)
        }
        sendBuffer = SendBuffer(firstSequence: sendBuffer.endSequence)
        outputs.append(.event(.closed(reason)))
    }
}
